import{_ as e,o as t,c as o,a3 as r}from"./chunks/framework.B9qR_F1m.js";const m=JSON.parse('{"title":"经济学","description":"微观经济学与宏观经济学笔记，用图形、公式与案例解释市场与国民收入。","frontmatter":{"title":"经济学","subject":"economics","subjectLabel":"经济学","description":"微观经济学与宏观经济学笔记，用图形、公式与案例解释市场与国民收入。"},"headers":[],"relativePath":"subjects/economics/index.md","filePath":"subjects/economics/index.md","lastUpdated":null}'),i={name:"subjects/economics/index.md"};function l(n,a,s,c,d,u){return t(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="经济学" tabindex="-1">经济学 <a class="header-anchor" href="#经济学" aria-label="Permalink to &quot;经济学&quot;">​</a></h1><p>经济学部分按 <strong>微观 / 宏观</strong> 两条主线组织。微观从个体决策出发，宏观从总量核算出发，两者通过 &quot;加总&quot; 与 &quot;预期&quot; 连接。公式统一用 LaTeX 书写，图形用文字描述其形状与移动方向。</p><h2 id="分类导航" tabindex="-1">分类导航 <a class="header-anchor" href="#分类导航" aria-label="Permalink to &quot;分类导航&quot;">​</a></h2><h3 id="微观经济学" tabindex="-1">微观经济学 <a class="header-anchor" href="#微观经济学" aria-label="Permalink to &quot;微观经济学&quot;">​</a></h3><ul><li><a href="./micro/supply-demand-elasticity">供需与弹性（写作模板）</a> —— 均衡价格、弹性与总收益</li><li><a href="./micro/market-structure">市场结构</a> —— 完全竞争、垄断、垄断竞争与寡头</li></ul><h3 id="宏观经济学" tabindex="-1">宏观经济学 <a class="header-anchor" href="#宏观经济学" aria-label="Permalink to &quot;宏观经济学&quot;">​</a></h3><ul><li><a href="./macro/gdp-and-national-income">GDP 与国民收入</a> —— 支出法核算、名义与实际 GDP</li></ul><h2 id="写作约定" tabindex="-1">写作约定 <a class="header-anchor" href="#写作约定" aria-label="Permalink to &quot;写作约定&quot;">​</a></h2><ul><li>每一个模型都按「<strong>假设 → 均衡 → 比较静态 → 现实偏离</strong>」四段写；</li><li>公式中的变量第一次出现时必须写明含义与单位；</li><li>结论要区分&quot;<strong>模型结论</strong>&quot;与&quot;<strong>现实判断</strong>&quot;，不要把理想化假设下的结论直接当作政策建议。</li></ul><blockquote><p><strong>提示</strong>：正文中若出现美元符号 <code>$</code>，需转义为 <code>\\$</code>，否则会被当作公式起始符。</p></blockquote>',10)])])}const _=e(i,[["render",l]]);export{m as __pageData,_ as default};
